import{_ as o,o as a,c,a5 as e,j as t,a as d}from"./chunks/framework.D47SInms.js";const i="/RBQ/nightly/images/app/home-motion-more.pc.ko.png",l="/RBQ/nightly/images/app/home-drive.pc.ko.png",y=JSON.parse('{"title":"모션 명령","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/motion-commands.md","filePath":"ko/manual/gui/motion-commands.md","lastUpdated":1791600043000}'),n={name:"ko/manual/gui/motion-commands.md"};function s(h,r,p,m,g,b){return a(),c("div",null,[...r[0]||(r[0]=[e('<h1 id="모션-명령" tabindex="-1">모션 명령 <a class="header-anchor" href="#모션-명령" aria-label="Permalink to &quot;모션 명령&quot;">​</a></h1><p>모션 명령은 <a href="/RBQ/nightly/ko/manual/gui/control-home.html">제어 홈</a> 왼쪽의 모션 카드에서 보냅니다. 짧게 탭하면 즉시 명령이 나가고, 로봇의 현재 보행 상태와 맞는 버튼이 강조됩니다.</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>여기 있는 명령은 모두 실제 로봇을 움직입니다. 누르기 전에 <strong>사람·동물·장애물을 2 m 이상 떨어뜨리고</strong>, 로봇이 <strong>자동 기동</strong>을 마치고 안정된 바닥에 서 있는지 확인하세요.</p></div><h2 id="고정-버튼" tabindex="-1">고정 버튼 <a class="header-anchor" href="#고정-버튼" aria-label="Permalink to &quot;고정 버튼&quot;">​</a></h2><table tabindex="0"><thead><tr><th>버튼</th><th>로봇 동작</th></tr></thead><tbody><tr><td><code>SIT</code></td><td>앉은 자세로 접습니다. 조이스틱 입력은 무시됩니다</td></tr><tr><td><code>STAND</code></td><td>앉아 있으면 일어섭니다. 보행·계단 중이면 멈춰서 제자리에 섭니다</td></tr><tr><td><code>WALK</code></td><td>보행을 시작합니다 — 이제 조이스틱이 로봇을 움직입니다</td></tr><tr><td><code>STAIRS</code></td><td>계단 보행: 걸음이 느려지고 몸체가 경사에 맞춰 기울어집니다</td></tr><tr><td><code>DOCKING</code></td><td>충전 도크까지 스스로 걸어가 올라갑니다. 도킹이 가능할 때만 버튼이 나옵니다 — Rapid 로봇에는 제공되지 않으며, 비전 토글 <code>DOCK 스캔</code>이 켜진 동안에는 사라집니다(영상 위 도킹 오버레이가 대신합니다)</td></tr></tbody></table><p>버튼 두 개에는 모서리에 작은 점이 있습니다. <strong>길게 누르면</strong> 하위 목록이 열립니다.</p><ul><li><code>SIT</code> 길게 누르기 → <strong>Static · Calib</strong>: <code>ZMP Calibrate</code>(서 있는 상태에서 균형 보정).</li><li><code>WALK</code> 길게 누르기 → <strong>Dynamic Motions</strong>: <code>Model Walk</code>(모델 기반 기본 보행), <code>Wave</code>, <code>Run</code>. <code>Run</code>은 휠 로봇에서는 제공되지 않습니다.</li></ul><h3 id="앉기" tabindex="-1">앉기 <a class="header-anchor" href="#앉기" aria-label="Permalink to &quot;앉기&quot;">​</a></h3>',8),t("figure",{style:{"text-align":"center",margin:"1rem 0"}},[t("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/eqR7WaP2d-o",title:"앉기",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),t("figcaption",{style:{"text-align":"center","margin-top":"0.5rem",color:"var(--vp-c-text-2, #666)","font-size":"0.95em"}},"앉기")],-1),t("h3",{id:"서기",tabindex:"-1"},[d("서기 "),t("a",{class:"header-anchor",href:"#서기","aria-label":'Permalink to "서기"'},"​")],-1),t("figure",{style:{"text-align":"center",margin:"1rem 0"}},[t("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/6QEGjlFkftI",title:"서기",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),t("figcaption",{style:{"text-align":"center","margin-top":"0.5rem",color:"var(--vp-c-text-2, #666)","font-size":"0.95em"}},"서기")],-1),e('<p>서 있는 동안 조이스틱은 로봇을 이동시키지 않고 자세를 조정합니다.</p><table tabindex="0"><thead><tr><th>조이스틱</th><th>입력</th><th>로봇 동작</th></tr></thead><tbody><tr><td>L 스틱</td><td>앞 / 뒤</td><td>고개 위 / 아래</td></tr><tr><td>L 스틱</td><td>좌 / 우</td><td>좌 / 우 롤</td></tr><tr><td>R 스틱</td><td>앞 / 뒤</td><td>높이 올리기 / 내리기</td></tr><tr><td>R 스틱</td><td>좌 / 우</td><td>좌 / 우 회전</td></tr></tbody></table><h3 id="보행" tabindex="-1">보행 <a class="header-anchor" href="#보행" aria-label="Permalink to &quot;보행&quot;">​</a></h3>',3),t("figure",{style:{"text-align":"center",margin:"1rem 0"}},[t("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/x3d95WWxFF0",title:"보행",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),t("figcaption",{style:{"text-align":"center","margin-top":"0.5rem",color:"var(--vp-c-text-2, #666)","font-size":"0.95em"}},"보행")],-1),e('<table tabindex="0"><thead><tr><th>조이스틱</th><th>입력</th><th>로봇 동작</th></tr></thead><tbody><tr><td>L 스틱</td><td>앞 / 뒤</td><td>전진 / 후진</td></tr><tr><td>L 스틱</td><td>좌 / 우</td><td>좌 / 우 이동</td></tr><tr><td>R 스틱</td><td>앞 / 뒤</td><td>피치 앞 / 뒤</td></tr><tr><td>R 스틱</td><td>좌 / 우</td><td>좌 / 우 회전</td></tr></tbody></table><h3 id="계단" tabindex="-1">계단 <a class="header-anchor" href="#계단" aria-label="Permalink to &quot;계단&quot;">​</a></h3>',2),t("figure",{style:{"text-align":"center",margin:"1rem 0"}},[t("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/dq6S16V7oyE",title:"계단",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),t("figcaption",{style:{"text-align":"center","margin-top":"0.5rem",color:"var(--vp-c-text-2, #666)","font-size":"0.95em"}},"계단")],-1),e('<table tabindex="0"><thead><tr><th>조이스틱</th><th>입력</th><th>로봇 동작</th></tr></thead><tbody><tr><td>L 스틱</td><td>앞 / 뒤</td><td>전진 / 후진</td></tr><tr><td>L 스틱</td><td>좌 / 우</td><td>좌 / 우 이동</td></tr><tr><td>R 스틱</td><td>좌 / 우</td><td>좌 / 우 회전</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>계단과 경사에서는 천천히, 똑바로 접근하세요. 로봇이 자세를 맞추는 동안 손으로 개입하지 마세요.</p></div><h2 id="더-많은-모션" tabindex="-1">더 많은 모션 <a class="header-anchor" href="#더-많은-모션" aria-label="Permalink to &quot;더 많은 모션&quot;">​</a></h2><p>카드 맨 아래의 점선 버튼 <strong>모션</strong>을 누르면 <strong>모션 선택</strong> 그리드가 열립니다(<em>탭하면 즉시 실행 후 닫힘</em>). 타일을 탭하면 그 모션이 전송되고 그리드가 닫힙니다.</p><p><img src="'+i+'" alt="모션 선택"></p><p><code>STAIRS</code>와 <code>DOCKING</code>은 그리드에 <strong>없습니다</strong> — 이미 모션 카드에 버튼으로 있습니다.</p><p><strong>모델 보행</strong></p><table tabindex="0"><thead><tr><th>타일</th><th>로봇 동작</th></tr></thead><tbody><tr><td><code>Wave</code></td><td>손 흔들기 동작</td></tr><tr><td><code>Run</code></td><td>빠른 트롯</td></tr><tr><td><code>Model Walk</code></td><td>모델 기반 기본 보행</td></tr></tbody></table><p><strong>AI 모션</strong></p><p>로봇의 학습된(AI) 정책으로 움직이는 보행입니다. 타일을 탭하면 바로 실행됩니다.</p><div class="warning custom-block"><p class="custom-block-title">AI 모션</p><p>일부 AI 모션은 뛰거나 달리거나 두·세 다리로 균형을 잡습니다. 먼저 로봇을 세우고, 사방 2 m 이상을 비우고, 평평하고 미끄럽지 않은 바닥에서 쓰세요.</p></div><table tabindex="0"><thead><tr><th>타일</th><th>로봇 동작</th></tr></thead><tbody><tr><td><code>AI Walk</code></td><td>학습된 정책으로 걷습니다</td></tr><tr><td><code>AI Vision</code></td><td>카메라로 지형을 읽으며 학습된 정책으로 걷습니다</td></tr><tr><td><code>AI Vision Slow</code></td><td><code>AI Vision</code> 과 같되 더 천천히 걷습니다</td></tr><tr><td><code>AI Pronk</code></td><td>네 다리를 함께 모아 뜁니다</td></tr><tr><td><code>AI Bound</code></td><td>바운드 보행 — 앞다리 한 쌍과 뒷다리 한 쌍이 함께 움직입니다</td></tr><tr><td><code>AI Pace</code></td><td>페이스 보행 — 같은 쪽 다리가 함께 움직입니다</td></tr><tr><td><code>AI Run</code></td><td>빠르게 달립니다</td></tr><tr><td><code>AI 2Leg L</code> / <code>AI 2Leg R</code> / <code>AI 2Leg F</code></td><td>두 다리로 균형을 잡습니다(왼쪽·오른쪽·앞쪽 한 쌍)</td></tr><tr><td><code>AI 3Leg HL</code></td><td>왼쪽 뒷다리를 들고 세 다리로 균형을 잡습니다</td></tr></tbody></table><p><strong>정밀·보정</strong></p><table tabindex="0"><thead><tr><th>타일</th><th>로봇 동작</th></tr></thead><tbody><tr><td><code>무게 중심 보정</code></td><td>균형 보정 — <code>SIT</code> 길게 누르기 목록의 <code>ZMP Calibrate</code>와 같습니다</td></tr></tbody></table><blockquote><p><strong>개발자 모드에서 더 나오는 것</strong>은 <a href="/RBQ/nightly/ko/manual/gui/developer-mode.html#motion">개발자 모드</a>에 모아 두었습니다.</p></blockquote><div class="warning custom-block"><p class="custom-block-title">도킹</p><p>도킹 중에는 로봇이 스스로 움직입니다. 밀거나 방향을 바꾸지 말고, 도크가 올바른 위치에 놓여 있고 전원이 들어와 있는지 확인하세요. 도크에 올라가면 로봇은 멈추고 충전을 시작합니다.</p></div><h2 id="drive-parameters" tabindex="-1">주행 파라미터 <a class="header-anchor" href="#drive-parameters" aria-label="Permalink to &quot;주행 파라미터 {#drive-parameters}&quot;">​</a></h2><p>왼쪽 조이스틱 옆 도구 버튼에서 <strong>주행</strong>을 탭하면 <strong>주행 파라미터</strong> 팝오버가 열립니다.</p><p><img src="'+l+'" alt="주행 파라미터"></p><table tabindex="0"><thead><tr><th>항목</th><th>범위</th><th>효과</th></tr></thead><tbody><tr><td><code>Vision Walk</code></td><td>켜기 / 끄기</td><td><code>WALK</code> 중에 카메라를 활용하는 보행 정책을 씁니다. 보행 중에 바꾸면 즉시 정책이 교체됩니다</td></tr><tr><td><code>Max Speed</code></td><td>0.50 – 2.50 m/s</td><td>조이스틱으로 낼 수 있는 보행 속도의 상한</td></tr><tr><td><code>Body Height</code></td><td>−0.25 – +0.10 m</td><td>기본 자세 대비 서 있는 높이 오프셋</td></tr><tr><td><code>Body Tilt</code></td><td>−25° – +25°</td><td>보행 중 몸체의 고정 피치</td></tr><tr><td><strong>기본값 복귀</strong></td><td>—</td><td>속도 1.0 m/s, 높이 0, 기울기 0으로 되돌립니다</td></tr></tbody></table><p>슬라이더 값은 드래그 중이 아니라 손을 뗄 때 로봇에 전송됩니다.</p>',21),t("figure",{style:{"text-align":"center",margin:"1rem 0"}},[t("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/2DynPHB6U64",title:"주행 파라미터",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),t("figcaption",{style:{"text-align":"center","margin-top":"0.5rem",color:"var(--vp-c-text-2, #666)","font-size":"0.95em"}},"주행 파라미터")],-1),t("blockquote",null,[t("p",null,[t("strong",null,"개발자 모드에서 더 나오는 것"),d("은 "),t("a",{href:"/RBQ/nightly/ko/manual/gui/developer-mode.html#control-home"},"개발자 모드"),d("에 모아 두었습니다.")])],-1)])])}const _=o(n,[["render",s]]);export{y as __pageData,_ as default};
